import {esc,input,select,button} from '../phase4/ui.js';
import * as G from './b23-geometry.js';
import {axes,classes,compassPoints,gridPoints,inspect,pieceStep,pixels,requiredMeet} from './b23-model.js';
const btn=(a,l,x='')=>button('g23-'+a,l,x),f=(k,l,v)=>input(k,l,v).replace('maxlength="2000"','maxlength="1500"'),sel=(k,l,v,o)=>select(k,l,v,o),note=s=>`<p class="g23-note">${s}</p>`,card=s=>`<div class="g23-card">${s}</div>`,fmt=n=>Number.isFinite(n)?String(Math.round(n*100)/100):'—';
const fold=(v,yes)=>yes?`<details class="g23-fold"><summary>查看或修改刚才的操作</summary>${v}</details>`:v;
const qfields=(t,m)=>(t.questions||[]).map((q,i)=>q.options?sel('answers.'+i,q.label,m.answers[i],q.options):f('answers.'+i,q.label,m.answers[i])).join('');
const done=(t,m)=>inspect(t,{...m,answers:(t.questions||[]).map(q=>String(q.value))}).correct;
const line=(a,b,attrs='')=>`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" ${attrs}/>`;
const polygon=(ps,attrs='')=>`<polygon points="${ps.map(p=>p.join(',')).join(' ')}" ${attrs}/>`;
const path=(ps,attrs='')=>`<polyline points="${ps.map(p=>p.join(',')).join(' ')}" fill="none" ${attrs}/>`;
const svg=(body,label,view='0 0 700 330')=>`<svg class="g23-svg" viewBox="${view}" role="img" aria-label="${esc(label)}">${body}</svg>`;
function mapPoints(ps,w=700,h=300){const xs=ps.map(p=>p[0]),ys=ps.map(p=>p[1]),cx=(Math.min(...xs)+Math.max(...xs))/2,cy=(Math.min(...ys)+Math.max(...ys))/2,s=Math.min((w-2*Math.min(55,w*.12))/(Math.max(...xs)-Math.min(...xs)||1),(h-2*Math.min(35,h*.12))/(Math.max(...ys)-Math.min(...ys)||1));return ps.map(([x,y])=>[w/2+(x-cx)*s,h/2-(y-cy)*s]);}
const basic=(ps,label)=>svg(polygon(mapPoints(ps), 'fill="#e6cba4" fill-opacity=".55" stroke="#58786e" stroke-width="3"'),label);
function cardShape(c){if(c.kind==='circle')return'<circle cx="60" cy="47" r="28" fill="#ddc4a8" stroke="#536f68" stroke-width="3"/>';const p=mapPoints(c.points,120,94);if(c.kind==='open')return path(p,'stroke="#536f68" stroke-width="3"');if(c.kind==='curve')return `<path d="M${p[0]} Q${(p[0][0]+p[1][0])/2},${(p[0][1]+p[1][1])/2-18} ${p[1]} L${p[2]} Z" fill="#ddc4a8" stroke="#536f68" stroke-width="3"/>`;return polygon(p,'fill="#ddc4a8" stroke="#536f68" stroke-width="3"');}
function picks(t,b){return`<div class="g23-cards">${t.cards.map((c,i)=>btn('toggle',`<svg viewBox="0 0 120 94" aria-hidden="true">${cardShape(c)}</svg><span>${i+1}</span>`,`data-index="${i}" aria-label="图形${i+1}" aria-pressed="${b.selected.includes(i)}" class="g23-shapecard ${b.selected.includes(i)?'on':''}"`)).join('')}</div>`+note(`点图形选择，再点一次取消。已选 ${b.selected.length} 个。`);}
function nested(t,b){const cards=`<div class="g23-cards">${t.cards.map((c,i)=>`<div class="g23-shapecard"><svg viewBox="0 0 120 94" aria-hidden="true">${cardShape(c)}</svg><span>图形${i+1}</span></div>`).join('')}</div>`;let body='<rect x="40" y="35" width="620" height="255" rx="16" fill="#edf1e6" stroke="#8ba998"/><text x="55" y="60">四边形</text><rect x="230" y="83" width="385" height="165" rx="15" fill="#dcebe0" stroke="#7ea492"/><text x="242" y="108">长方形</text><rect x="440" y="133" width="135" height="75" rx="12" fill="#c4dfcf" stroke="#638f79"/><text x="449" y="155">正方形</text>';const used=[0,0,0];b.assigned.forEach((r,i)=>{if(r===null)return;const pos=[[100,95],[275,142],[470,180]][r],x=pos[0]+(used[r]%2)*58,y=pos[1]+Math.floor(used[r]/2)*38;used[r]++;body+=`<circle cx="${x}" cy="${y}" r="16" fill="#fdfaf0" stroke="#618a77"/><text x="${x}" y="${y+5}" text-anchor="middle">${i+1}</text>`;});return cards+svg(body,'四边形包含长方形，长方形包含正方形')+note('数字对应上面的图形；放在最里面仍属于包住它的范围。');}
function polygonBoard(t,b){const base=gridPoints(t),ps=t.preset?base.map(([x,y])=>[180+55*x,145+55*y]):base.map(([x,y])=>[35+40*x,25+40*y]),chosen=b.points.map(i=>ps[i]),outline=(b.closed?polygon(chosen,'fill="#dac4a4" fill-opacity=".55" stroke="#55796a" stroke-width="3"'):path(chosen,'stroke="#55796a" stroke-width="3"'));
 return`<div class="g23-draw" style="height:290px">${svg(outline,'按选点顺序连接的边','0 0 310 290')}${ps.map((p,i)=>{const n=b.points.indexOf(i);return btn('add',n>=0?String(n+1):'',`data-index="${i}" aria-label="点${i+1}${n>=0?'，已选第'+(n+1)+'个':''}" class="g23-dot ${n>=0?'on':''}" style="left:${p[0]}px;top:${p[1]}px"`);}).join('')}</div>`+note(`按顺序点 ${t.n} 个点，然后闭合。已点 ${b.points.length}/${t.n}。`);}
function tilePath(t,angle,color){let p='';if(t.pattern==='rect')p='<path d="M-115 -58 L115 -58 L-115 58 Z"/>';if(t.pattern==='hex')p='<path d="M0 0 L108 0 L54 -93.53 Z"/>';if(t.pattern==='quarters')p='<path d="M0 0 L108 0 A108 108 0 0 1 0 108 Z"/>';if(t.pattern==='halves')p='<path d="M-108 0 A108 108 0 0 1 108 0 Z"/>';return`<g transform="translate(350 155) rotate(${angle})" fill="${color}" fill-opacity=".72" stroke="#55756a" stroke-width="2">${p}</g>`;}
function tiles(t,b){const outline=t.pattern==='rect'?'<rect x="235" y="97" width="230" height="116"/>':t.pattern==='hex'?polygon(G.regular(6,108,0).map(([x,y])=>[350+x,155+y])):'<circle cx="350" cy="155" r="108"/>';let s=`<g fill="none" stroke="#a6b6ad" stroke-width="3" stroke-dasharray="5 5">${outline}</g>`;const colors=['#9fc8b3','#e3b68d','#9bb6cc','#d8c484','#c3add0','#e1a6a3'];b.slots.forEach((p,i)=>{if(p!==null)s+=tilePath(t,b.rotations[p],colors[p%colors.length]);});return svg(s,'小块在目标轮廓中的实际位置')+note(`已放 ${b.slots.filter(x=>x!==null).length}/${t.slots} 块。小块绕中心转动；重叠处颜色会加深。`);}
function sides(t,b){const p=mapPoints(G.scenario(t.shape,t.rotation)),n=p.length;return svg(polygon(p,'fill="#e6cba4" fill-opacity=".45" stroke="#a7b5aa" stroke-width="2"')+p.map((q,i)=>{const r=p[(i+1)%n],a=[(q[0]+r[0])/2,(q[1]+r[1])/2];return line(q,r,`stroke="${b.marked.includes(i)?'#cc8d4a':'#678c7b'}" stroke-width="${b.marked.includes(i)?8:3}"`)+`<text x="${a[0]}" y="${a[1]-9}" text-anchor="middle">${i+1}</text>`;}).join(''),'图形的每条边都有编号')+note(`已点亮 ${b.marked.length}/${n} 条边。`);}
function symmetry(t,b){const ps=G.scenario(t.shape,t.rotation),S=49,X=p=>[350+p[0]*S,165-p[1]*S],original=ps.map(X);let v=polygon(original,'fill="#e4c2a0" fill-opacity=".48" stroke="#4e776b" stroke-width="3"');
 if(b.last!==null){const a=t.candidates[b.last],rad=a*Math.PI/180,d=[Math.cos(rad)*260,-Math.sin(rad)*260];v+=line([350-d[0],165-d[1]],[350+d[0],165+d[1]],'stroke="#b37a4c" stroke-width="2" stroke-dasharray="7 5"');v+=polygon(ps.map(p=>X(G.reflect(p,a))),'fill="#8db9ca" fill-opacity=".24" stroke="#668eaa" stroke-width="3" stroke-dasharray="6 4"');}
 if(t.turn&&b.turns)v+=polygon(ps.map(p=>X(G.rotate(p,b.turns*60))),'fill="none" stroke="#b98742" stroke-width="5" stroke-dasharray="2 5"');
 return svg(v,'原图与候选线反射后的图形')+note(b.last===null?'选择一条线试试看；蓝色轮廓是反射后的图。':`刚试 ${t.candidates[b.last]}°：${G.symmetric(ps,t.candidates[b.last])?'整个轮廓重合':'没有完全重合'}。已试 ${b.tested.length}/${t.candidates.length} 条。`)+(t.turn&&b.turns?note(`已转 ${b.turns*60}°；金色虚线是转动后的轮廓。`):'');}
function quadrilateral(t,b){const ps=G.scenario(t.shape,t.rotation),p=mapPoints(ps),prop=G.properties(ps);return basic(ps,'正在检查的图形')+card(`<p>${b.tested.includes(0)?'边长：'+prop.sides.map(fmt).join('、'):'边长：还没检查'}</p><p>${b.tested.includes(1)?'各个角：'+prop.angles.map(x=>fmt(x)+'°').join('、'):'角：还没检查'}</p><p>${b.tested.includes(2)?'两组对边分别平行：'+(prop.parallel?'是':'否'):'对边：还没检查'}</p>`);}
function linesView(t,b){const ps=G.scenario(t.shape,t.rotation),p=mapPoints(ps),v=polygon(p,'fill="#e7cba5" fill-opacity=".45" stroke="#618476" stroke-width="3"')+p.map((a,i)=>{const z=p[(i+1)%p.length];return`<text x="${(a[0]+z[0])/2}" y="${(a[1]+z[1])/2-9}" text-anchor="middle">边${i+1}</text>`;}).join('');let s=svg(v,'每条边都有编号');if(b.tests.length)s+=card(b.tests.slice(-4).map(x=>`<p>边${x.first+1}与边${x.second+1}：${x.parallel?'平行':x.perpendicular?'垂直':'既不平行也不垂直'}</p>`).join(''));return s+note('比较的是边所在的直线：可以想象向两端继续延长。');}
function ruler(t,b){return b.drawing?basic(b.drawing.points,'按照输入的尺寸画出的图形')+note('屏幕按输入生成图形；不代表已经会使用实物尺子。'):card('填入尺寸后，图形会画在这里。');}
function objectsView(t,b){const labels={cylinder:'圆柱',cuboid:'长方体',cube:'正方体',sphere:'球'},shape=b.shape;let s=card(`<b>水平地面上的简化模型</b><p>选择：${labels[shape]||'还没选'}${shape?' · '+(b.orientation==='upright'?'立着':'侧放'):''}</p><p>${b.rolled?'已沿曲面滚动。':''}${b.stacked?'已在平面上叠放。':''}</p>`);const icon=shape==='cylinder'?(b.orientation==='upright'?'<ellipse cx="350" cy="93" rx="75" ry="25"/><path d="M275 93 V220 Q350 270 425 220 V93"/><ellipse cx="350" cy="93" rx="75" ry="25"/>':'<path d="M260 115 H440 V215 H260 Z"/><ellipse cx="260" cy="165" rx="24" ry="50"/><ellipse cx="440" cy="165" rx="24" ry="50"/>'):shape==='sphere'?'<circle cx="350" cy="165" r="75"/>':shape?'<path d="M260 120 L385 120 L430 85 L305 85 Z M260 120 V220 H385 V120 M385 220 L430 185 V85"/>':'';s+=svg(`<g fill="#dfc3a1" stroke="#5b7c6e" stroke-width="3">${icon}</g>`,'当前选择的立体形状');if(t.required.includes('pack'))s+=`<div class="g23-packs">${Array.from({length:4},(_,i)=>btn('pack',b.packed.includes(i)?'已放':'放一块',`data-index="${i}" class="${b.packed.includes(i)?'on':''}"`)).join('')}</div>`;return s+note('这里只比较没有额外支撑时的简单摆放；现实还受尺寸和材料影响。');}
function pieceIcon(kind,x,y){const shapes={cuboid:'<path d="M-45 -5 L20 -5 L38 -20 L-27 -20 Z M-45 -5 V35 H20 V-5 M20 35 L38 20 V-20"/>',roof:'<path d="M-50 5 L-10 -35 L30 5 Z M-10 -35 L20 -45 L60 -5 L30 5"/>',rectangle:'<rect x="-52" y="-14" width="104" height="28"/>',triangle:'<path d="M-44 30 L0 -30 L44 30 Z"/>',slope:'<path d="M-50 -5 L-40 -22 L50 22 L40 38 Z"/>'};return`<g transform="translate(${x} ${y})" fill="#d8b995" stroke="#597a6b" stroke-width="3">${shapes[kind]||''}</g>`;}
function scene(t,b){if(t.sceneType==='house'){const body=b.slots[0]?pieceIcon(b.slots[0],350,185):'<path d="M305 180 L370 180 L388 165 L323 165 Z M305 180 V220 H370 V180 M370 220 L388 205 V165" fill="none" stroke="#b9c9b8" stroke-width="2" stroke-dasharray="5 4"/><text x="345" y="207" text-anchor="middle">位置1</text>',roof=b.slots[1]?pieceIcon(b.slots[1],350,160):'<path d="M300 165 L340 125 L380 165 Z M340 125 L370 115 L410 155 L380 165" fill="none" stroke="#b9c9b8" stroke-width="2" stroke-dasharray="5 4"/><text x="350" y="151" text-anchor="middle">位置2</text>';return svg(body+roof,'由所选形状组成的简化小屋','230 90 250 170')+note('房身与屋顶各有一个位置；这只是对真实房子的简化。');}const pos=[[230,125],[340,190],[450,155]];return svg(pos.map(([x,y],i)=>`<rect x="${x-70}" y="${y-55}" width="140" height="110" rx="8" fill="none" stroke="#d2cabb" stroke-dasharray="4 4"/>`+(b.slots[i]?pieceIcon(b.slots[i],x,y):`<text x="${x}" y="${y}" text-anchor="middle">位置${i+1}</text>`)).join(''),'由所选形状组成的简化图')+note('虚线框提示要放的位置；这只是对真实物体的简化。');}
function pixelView(b){return`<div class="g23-pixelboard"><svg viewBox="0 0 350 350" aria-hidden="true"><path d="M92 247 Q50 152 111 83 Q152 32 211 60 Q237 72 213 110 Q210 150 237 166 Q200 199 197 240 Q164 292 92 247Z" fill="#cfe4ca" stroke="#8dab90" stroke-width="3"/></svg>${Array.from({length:49},(_,i)=>btn('toggle','',`data-index="${i}" aria-label="第${Math.floor(i/7)+1}行第${i%7+1}格" aria-pressed="${b.selected.includes(i)}" class="${b.selected.includes(i)?'on':''}"`)).join('')}</div>`+note(`已涂 ${b.selected.length} 格。尽量覆盖绿色叶形，允许边缘有误差。`);}
function circleView(b){const r=b.radius===null?0:b.radius*16,a=b.turns*Math.PI/4,dx=Math.cos(a)*r,dy=Math.sin(a)*r;let s=b.radius===null?'':`<circle cx="350" cy="160" r="${r}" fill="#e6cba4" fill-opacity=".3" stroke="${b.rim?'#c27f42':'#547a6e'}" stroke-width="${b.rim?6:3}"/><circle cx="350" cy="160" r="4" fill="#476f63"/>`;if(b.radial)s+=line([350,160],[350+r,160],'stroke="#c27f42" stroke-width="4"');if(b.diameter)s+=line([350-dx,160-dy],[350+dx,160+dy],'stroke="#648eaa" stroke-width="4"');return svg(s,'圆心、半径和可转动的直径')+note(b.radius===null?'先画一个圆。':`圆心到边缘 ${fmt(b.radius)} 厘米。${b.diameter?'蓝线穿过圆心连接两边。':''}`);}
function notationView(b){let s='<rect x="170" y="70" width="360" height="190" fill="#e6cba4" fill-opacity=".35" stroke="#587b6e" stroke-width="3"/>';for(const[x,y,n]of[[160,60,'A'],[540,60,'B'],[540,280,'C'],[160,280,'D']])s+=`<text x="${x}" y="${y}" font-weight="bold">${n}</text>`;return svg(s,'四个点按A B C D环绕的长方形')+(b.saved?card(`你写下：${esc(b.saved.segment)}；∠${esc(b.saved.angleName.replace(/^∠/,''))}；${esc(b.saved.parallelName)}；${esc(b.saved.perpName)}`):'');}
const centers=t=>t.mode==='bisector'?{A:[2,5],B:[8,5]}:t.mode==='angle'?{O:[2,2],C:[4,2],D:[2,4]}:{P:[5,8],C:[1,5],D:[9,5]};
function compassView(t,b){const cs=centers(t),X=([x,y])=>[175+x*35,490-y*35],r=35;const extent=t.mode==='bisector'?[cs.A,cs.B]:t.mode==='angle'?[cs.O,[8,2],[2,8]]:[cs.P,[0,5],[10,5]];for(const[k,rad]of Object.entries(b.circles)){const [x,y]=cs[k];extent.push([x-rad,y-rad],[x+rad,y+rad]);}const px=extent.map(X),xs=px.map(p=>p[0]),ys=px.map(p=>p[1]),x0=Math.min(...xs)-35,y0=Math.min(...ys)-35,view=`${x0} ${y0} ${Math.max(...xs)-x0+35} ${Math.max(...ys)-y0+35}`;let s='';if(t.mode==='bisector')s+=line(X(cs.A),X(cs.B),'stroke="#53766c" stroke-width="4"');if(t.mode==='angle')s+=line(X(cs.O),X([8,2]),'stroke="#53766c" stroke-width="4"')+line(X(cs.O),X([2,8]),'stroke="#53766c" stroke-width="4"');if(t.mode==='perpendicular')s+=line(X([0,5]),X([10,5]),'stroke="#53766c" stroke-width="4"');
 for(const[k,rad]of Object.entries(b.circles)){const[x,y]=X(cs[k]);s+=`<circle cx="${x}" cy="${y}" r="${rad*r}" fill="none" stroke="${['A','C','O','P'].includes(k)?'#c6956b':'#82a6b1'}" stroke-width="2" opacity=".75"/>`;}
 const seedVisible=t.mode==='bisector'||t.mode==='angle'&&b.circles.O===2||t.mode==='perpendicular'&&b.circles.P===5;for(const[k,p]of Object.entries(cs)){if(['C','D'].includes(k)&&!seedVisible)continue;const[x,y]=X(p);s+=`<circle cx="${x}" cy="${y}" r="5" fill="#486e63"/><text x="${x+7}" y="${y-8}">${k}</text>`;}
 const pts=compassPoints(t,b);pts.forEach((p,i)=>{const[x,y]=X(p);s+=`<circle cx="${x}" cy="${y}" r="${b.marked.includes(i)?9:6}" fill="${b.marked.includes(i)?'#b66a3f':'#8eb5a1'}"/><text x="${x+10}" y="${y-8}">交点${i+1}</text>`;});if(b.finished){const points=t.mode==='bisector'?requiredMeet(t,b).map(i=>X(pts[i])):[X(cs[t.mode==='angle'?'O':'P']),X(pts[requiredMeet(t,b)[0]])];s+=line(points[0],points[1],'stroke="#c4673a" stroke-width="4"');}
 if(b.measured&&t.mode==='angle'){const p=pts[requiredMeet(t,b)[0]],theta=Math.atan2(p[1]-cs.O[1],p[0]-cs.O[0])*180/Math.PI;s+=`<text x="${x0+12}" y="${y0+22}" fill="#9c683d">两边的角：${fmt(theta)}° 和 ${fmt(90-theta)}°</text>`;}return svg(s,'实际画出的圆、交点和连接线',view)+note('画出的整圈保留着，圆弧是圆周的一部分。屏幕上的直尺用于连接点。');}
export function visual(t,m){const b=m.board;let v='';
 if(t.type==='x-s23-pick')v=picks(t,b);
 if(t.type==='x-s23-nest')v=nested(t,b);
 if(t.type==='x-s23-polygon')v=polygonBoard(t,b);
 if(t.type==='x-s23-frame')v=`<div id="extra-world" class="cube-world"></div>`+note(t.mode==='build'?`已搭 ${b.edges.length}/12 根。拖动查看背面，也可以点立体上的边。`:'拖动立体或点下方转动按钮，看它换个方向。');
 if(t.type==='x-s23-tile')v=tiles(t,b);
 if(t.type==='x-s23-sides')v=sides(t,b);
 if(t.type==='x-s23-symmetry')v=symmetry(t,b);
 if(t.type==='x-s23-quad')v=quadrilateral(t,b);
 if(t.type==='x-s23-lines')v=linesView(t,b);
 if(t.type==='x-s23-ruler')v=ruler(t,b);
 if(t.type==='x-s23-objects')v=objectsView(t,b);
 if(t.type==='x-s23-scene')v=scene(t,b);
 if(t.type==='x-s23-pixels')v=pixelView(b);
 if(t.type==='x-s23-circle')v=circleView(b);
 if(t.type==='x-s23-notation')v=notationView(b);
 if(t.type==='x-s23-compass')v=compassView(t,b);
 return`<div class="g23-world">${v}</div>`;
}
export function controls(t,m){const b=m.board,complete=done(t,m);let v='',ready=true;
 if(t.type==='x-s23-pick')ready=b.selected.length>0;
 if(t.type==='x-s23-nest'){v=sel('item','选择图形',m.item,t.cards.map((_,i)=>[String(i),`图形${i+1}`]))+sel('slot','放进最里面符合的范围',m.slot,[['0','四边形范围'],['1','长方形范围'],['2','正方形范围']])+btn('sort','放进去');ready=b.assigned.every(x=>x!==null);}
 if(t.type==='x-s23-polygon'){v=btn('undo','退回一个点')+btn('close','连回起点');ready=b.closed;}
 if(t.type==='x-s23-frame'){v=button('turn-extra','转一转')+(t.mode==='build'?`<details class="g23-fold g23-edge-list"><summary>也可以从边的清单选择</summary><div class="g23-buttons">${G.CUBE_EDGES.map(([x,y],i)=>btn('stick',`${String.fromCharCode(65+x)}—${String.fromCharCode(65+y)}`,`data-index="${i}" class="${b.edges.includes(i)?'on':''}"`)).join('')}</div></details>`:'');ready=t.mode==='build'?b.edges.length===12:b.turns>0;}
 if(t.type==='x-s23-tile'){v=sel('piece','选择小块',m.piece,Array.from({length:t.slots},(_,i)=>[String(i),`小块${i+1}`]))+btn('rotate',`转${pieceStep(t)}°`)+btn('place','放到图里')+(t.decompose?btn('unplace','取出选中的小块'):'');ready=t.decompose?b.separated:b.slots.every(x=>x!==null);}
 if(t.type==='x-s23-sides'){v=`<div class="g23-buttons">${Array.from({length:G.shapes[t.shape].length},(_,i)=>btn('mark',`边${i+1}`,`data-index="${i}" class="${b.marked.includes(i)?'on':''}"`)).join('')}</div>`;ready=b.marked.length===G.shapes[t.shape].length;}
 if(t.type==='x-s23-symmetry'){v=`<p>先逐条试折线：</p><div class="g23-buttons">${t.candidates.map((a,i)=>btn('test',`${a}°${b.tested.includes(i)?' ✓':''}`,`data-index="${i}"`)).join('')}</div>`;if(b.tested.length)v+=`<p>把能完全重合的线留下：</p><div class="g23-buttons">${t.candidates.map((a,i)=>btn('mark',`${a}°`, `data-index="${i}" class="${b.marked.includes(i)?'on':''}"`)).join('')}${btn('none','一条也没有',`class="${b.none?'on':''}"`)}</div>`;if(t.turn)v+=btn('turn','把图形转60°');ready=b.tested.length===t.candidates.length&&(!t.turn||b.turns>0);}
 if(t.type==='x-s23-quad'){v=`<div class="g23-buttons">${['检查边长','检查角','检查对边'].map((x,i)=>btn('test',x,`data-index="${i}" class="${b.tested.includes(i)?'on':''}"`)).join('')}</div>`;if(b.tested.length===3)v+=`<p>可以同时选多个家族：</p><div class="g23-buttons">${['四边形','平行四边形','长方形','菱形','正方形','正多边形'].map((x,i)=>btn('class',x,`data-index="${i}" class="${b.selected.includes(i)?'on':''}"`)).join('')}</div>`;ready=b.tested.length===3;}
 if(t.type==='x-s23-lines'){const opts=Array.from({length:G.shapes[t.shape].length},(_,i)=>[String(i),`边${i+1}`]);v=sel('first','第一条边',m.first,opts)+sel('second','另一条边',m.second,opts)+btn('lineTest','延长并比较');ready=b.tests.length>0;}
 if(t.type==='x-s23-ruler'){v=f('first',t.mode==='triangle'?'第一条边（厘米）':t.mode==='rectangle'?'长（厘米）':'每条边（厘米）',m.first)+(t.mode!=='regular'?f('second',t.mode==='triangle'?'第二条边（厘米）':'宽（厘米）',m.second):'')+(t.mode!=='rectangle'?f('angle',t.mode==='triangle'?'两边夹角（度）':'每个内角（度）',m.angle):'')+btn('draw','按尺寸画出来');ready=!!b.drawing;}
 if(t.type==='x-s23-objects'){v=sel('choice','选择一个形状',m.choice,[['cylinder','圆柱'],['cuboid','长方体'],['cube','正方体'],['sphere','球']])+btn('object','拿出来');if(b.shape)v+=btn('flip','换个方向')+(t.required.includes('roll')?btn('roll','试着滚动'):'')+(t.required.includes('stack')?btn('stack','试着叠放'):'');ready=t.required.every(k=>k==='roll'?b.rolled:k==='stack'?b.stacked:b.packed.length===4);}
 if(t.type==='x-s23-scene'){v=sel('choice','选择形状',m.choice,[['cuboid','盒子块'],['roof','三角屋顶块'],['rectangle','长方形平台'],['triangle','三角支撑'],['slope','斜面']])+sel('slot','放在',m.slot,t.slots.map((_,i)=>[String(i),`位置${i+1} · ${t.sceneType==='house'?['房身','屋顶'][i]:['平台','支撑','斜面'][i]}`]))+btn('scene','放进去');ready=b.slots.every(x=>x!==null);}
 if(t.type==='x-s23-pixels')ready=b.selected.length>=6;
 if(t.type==='x-s23-circle'){v=f('radius','半径（厘米）',m.radius)+btn('circle','画圆')+(b.radius!==null?btn('radial','从圆心画到边缘')+btn('diameter','画穿过圆心的整条线')+btn('rim','描出圆的边缘')+(t.turn?btn('turn','把直径转一转'):''):'');ready=b.radial&&b.diameter&&b.rim&&(!t.turn||b.turns>0);}
 if(t.type==='x-s23-notation'){v=f('segment','写出上面的线段',m.segment)+f('angleName','以B为顶点的角，用三个字母',m.angleName)+f('parallelName','写一组平行关系（用∥或//）',m.parallelName)+f('perpName','写一组垂直关系（用⊥）',m.perpName)+btn('label','把记号写在一起');ready=!!b.saved;}
 if(t.type==='x-s23-compass'){const opts=Object.keys(centers(t)).map(c=>[c,c+'点']);v=sel('center','以哪个点为圆心',m.center,opts)+f('radius','圆规张口',m.radius)+btn('arc','画这一圈');const points=compassPoints(t,b);if(points.length)v+=`<p>标出需要的交点：</p><div class="g23-buttons">${points.map((_,i)=>btn('meet',`交点${i+1}`,`data-index="${i}" class="${b.marked.includes(i)?'on':''}"`)).join('')}</div>`+btn('line','用直尺连线');if(t.mode==='angle'&&b.finished)v+=btn('measure','量一量两边的角');ready=b.finished&&(t.mode!=='angle'||b.measured);}
 v=fold(v,complete);if(ready)v+=qfields(t,m);if(m.issue)v+=`<p class="g23-issue" role="status">${esc(m.issue)}</p>`;return`<div class="g23-controls">${v}<details class="g23-fold"><summary>用自己的话留下发现（可选）</summary>${f('prose','我的解释或新问题',m.prose)}<small>原话会保存，暂不自动判断这段解释。</small></details></div>`;
}
export const render=(t,m)=>`<div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}</div>`;
